<?php require __DIR__.'/includes/auth.php';require_login();require __DIR__.'/config/database.php';$message='';$error='';$items=$pdo->query('SELECT id,name,quantity FROM items ORDER BY name')->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$item_id=(int)($_POST['item_id']??0);$type=$_POST['movement_type']??'';$q=(int)($_POST['quantity']??0);if(!$item_id||!in_array($type,['in','out'],true)||$q<1)$error='Select an item and enter a valid quantity.';else{try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT quantity FROM items WHERE id=? FOR UPDATE');$s->execute([$item_id]);$current=(int)$s->fetchColumn();if($type==='out'&&$q>$current)throw new Exception('Not enough stock available.');$new=$type==='in'?$current+$q:$current-$q;$pdo->prepare('UPDATE items SET quantity=? WHERE id=?')->execute([$new,$item_id]);$pdo->prepare('INSERT INTO stock_movements(item_id,user_id,movement_type,quantity,notes) VALUES(?,?,?,?,?)')->execute([$item_id,$_SESSION['user_id'],$type,$q,trim($_POST['notes']??'')]);$pdo->commit();$message='Stock movement recorded successfully.';}catch(Exception $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}}$history=$pdo->query('SELECT sm.*,items.name item_name,users.name user_name FROM stock_movements sm JOIN items ON sm.item_id=items.id LEFT JOIN users ON sm.user_id=users.id ORDER BY sm.id DESC LIMIT 10')->fetchAll();?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SIMS | Stock Movement</title><link rel="stylesheet" href="assets/css/style.css"><style>.move-grid{display:grid;grid-template-columns:.9fr 1.1fr;gap:20px}.move-grid label{display:block;font-size:12px;font-weight:700;margin:15px 0}.move-grid input,.move-grid select,.move-grid textarea{display:block;width:100%;border:1px solid #e8e8f0;border-radius:7px;padding:11px;margin-top:7px;font:inherit}.move-grid textarea{height:70px;resize:vertical}.success{background:#dcfce7;color:#15803d;padding:10px;border-radius:7px;font-size:13px}@media(max-width:800px){.move-grid{grid-template-columns:1fr}}</style></head><body class="dashboard-page"><aside class="sidebar"><div class="logo"><span>✎</span><div><strong>SIMS</strong><small>Stationery Inventory</small></div></div><nav><a href="dashboard.php">▦ Dashboard</a><a href="inventory.php">▤ Inventory</a><a class="active" href="stock_movement.php">↕ Stock movement</a></nav><a class="logout" href="logout.php">⇥ Sign out</a></aside><main class="dashboard"><header><div><p class="eyebrow">INVENTORY › STOCK MOVEMENT</p><h1>Record Stock Movement</h1></div></header><?php if($message):?><p class="success"><?=htmlspecialchars($message)?></p><?php endif;?><?php if($error):?><p class="alert"><?=htmlspecialchars($error)?></p><?php endif;?><div class="move-grid"><form method="post" class="content-card"><h2>New Record</h2><label>Item *<select name="item_id" required><option value="">Select item</option><?php foreach($items as $item):?><option value="<?=$item['id']?>"><?=htmlspecialchars($item['name'])?> (<?=$item['quantity']?> available)</option><?php endforeach;?></select></label><label>Movement type *<select name="movement_type"><option value="in">Stock In</option><option value="out">Stock Out</option></select></label><label>Quantity *<input name="quantity" type="number" min="1" required></label><label>Notes<textarea name="notes" placeholder="Optional notes"></textarea></label><button class="primary-btn">Save Record</button></form><section class="content-card"><h2>Recent Movement</h2><table><thead><tr><th>Item</th><th>Type</th><th>Qty</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td><?=htmlspecialchars($h['item_name'])?></td><td><span class="badge <?=$h['movement_type']==='in'?'good':'low'?>">Stock <?=htmlspecialchars($h['movement_type'])?></span></td><td><?=$h['quantity']?></td></tr><?php endforeach;?></tbody></table></section></div></main></body></html>
